using System.Text;
using System.Text.Json;
using GregsEx.Flavors.Pcre2.Runtime.Composition;
using GregsEx.Tests.Flavors.Pcre2.Runtime.Composition;
using Xunit;

namespace GregsEx.Tests.Flavors.Pcre2.Runtime.Kernel;

public sealed class ParityCallbackFlagTests
{
    // Independent PCRE2 10.46/b2bd4254 static-library observations. Both
    // optimizer policies were observed separately in all four native domains.
    public static IEnumerable<TheoryDataRow<string>> NativeCases()
    {
        using var json = JsonDocument.Parse(Witnesses);
        foreach (var item in json.RootElement.EnumerateArray())
        {
            yield return new TheoryDataRow<string>(item.GetRawText());
        }
    }

    [Theory]
    [MemberData(nameof(NativeCases))]
    public void ActualCompiledCallbacksAgreeWithNativeFields(string witness)
    {
        using var json = JsonDocument.Parse(witness);
        var input = json.RootElement.GetProperty("input");
        var expected = json.RootElement.GetProperty("calls");
        var width = input.GetProperty("width").GetInt32();
        var flags = (Pcre2CompileFlags)input.GetProperty("compileFlags").GetUInt32();
        var domain = (width == 8 ? 0 : 2) + ((flags & Pcre2CompileFlags.Utf) != 0 ? 1 : 0);
        var opt = input.GetProperty("optimization");
        var profile = new Pcre2Profile((Pcre2CodeUnitWidth)width, flags,
            optimization: new(opt[0].GetBoolean(), opt[1].GetBoolean(), opt[2].GetBoolean()));
        string pattern = Text(input.GetProperty("patternUnits")), subject = Text(input.GetProperty("subjectUnits"));
        using var workspace = new Pcre2PreparedWorkspace(RuntimeFixture.Compile(pattern, domain, profile), RuntimeFixture.Capacity);
        var pairs = new Pcre2OffsetPair[8];
        var count = 0;
        int Inspect(Pcre2CalloutInfo info, ReadOnlySpan<Pcre2OffsetPair> captures)
        {
            Assert.True(count < expected.GetArrayLength(), input.GetProperty("id").GetString());
            var call = expected[count++];
            Assert.Equal(call.GetProperty("version").GetInt32(), info.Version);
            Assert.Equal(call.GetProperty("number").GetInt32(), info.Number);
            Assert.Equal(call.GetProperty("isString").GetBoolean(), info.IsString);
            Assert.False(info.HasMark);
            Assert.Equal(0, info.StringLength);
            Assert.Equal(call.GetProperty("subjectLength").GetInt32(), info.SubjectLength);
            Assert.Equal(call.GetProperty("captureTop").GetInt32(), info.CaptureTop);
            Assert.Equal(call.GetProperty("captureLast").GetInt32(), info.CaptureLast);
            Assert.Equal(call.GetProperty("startMatch").GetInt32(), info.StartMatch);
            Assert.Equal(call.GetProperty("currentPosition").GetInt32(), info.CurrentPosition);
            Assert.Equal(call.GetProperty("patternPosition").GetInt32(), info.PatternPosition);
            Assert.Equal(call.GetProperty("nextItemLength").GetInt32(), info.NextItemLength);
            Assert.Equal(call.GetProperty("stringOffset").GetInt32(), info.StringOffset);
            Assert.Equal(call.GetProperty("flags").GetInt32(), (int)info.Flags);
            var native = call.GetProperty("captures");
            for (var i = 0; i < native.GetArrayLength(); i++)
            {
                Assert.Equal(native[i].ValueKind == JsonValueKind.Null || native[i][0].ValueKind == JsonValueKind.Null ? default :
                    new Pcre2OffsetPair(true, native[i][0].GetInt32(), native[i][1].GetInt32()), captures[i]);
            }

            Assert.Equal(JsonValueKind.Null, call.GetProperty("markUnits").ValueKind);
            return call.GetProperty("returnCode").GetInt32();
        }
        var result = domain < 2
            ? workspace.Match(Encoding.UTF8.GetBytes(subject), 0, pairs, callbacks:
                new(Match: (in c, _) =>
                { Assert.True(c.Subject.SequenceEqual(Encoding.UTF8.GetBytes(subject))); Assert.True(c.Mark.IsEmpty); Assert.True(c.CalloutString.IsEmpty); return Inspect(c.Info, c.Captures); }))
            : workspace.Match(subject, 0, pairs, callbacks:
                new(Match: (in c, _) =>
                { Assert.True(c.Subject.SequenceEqual(subject)); Assert.True(c.Mark.IsEmpty); Assert.True(c.CalloutString.IsEmpty); return Inspect(c.Info, c.Captures); }));
        Assert.Equal(expected.GetArrayLength(), count);
        Assert.Equal(json.RootElement.GetProperty("result").GetProperty("returnCode").GetInt32(), result.NativeReturnCode);
        Assert.True(workspace.IsIdle);
    }
    private static string Text(JsonElement units) => new([.. units.EnumerateArray().Select(x => (char)x.GetInt32())]);

